package com.payflow.analytics;
import com.payflow.payment.*; import com.payflow.refund.RefundRepository; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.*; import java.time.format.TextStyle; import java.util.*;
@RestController @RequestMapping("/api/v1/analytics")
public class AnalyticsController {
 private final PaymentRepository payments; private final RefundRepository refunds; public AnalyticsController(PaymentRepository p,RefundRepository r){payments=p;refunds=r;}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(Authentication auth){var all=payments.findAllByMerchantId((String)auth.getDetails());var paymentIds=all.stream().map(Payment::getId).collect(java.util.stream.Collectors.toSet());BigDecimal volume=all.stream().filter(p->p.getCapturedAt()!=null).map(Payment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal refunded=refunds.findAll().stream().filter(x->paymentIds.contains(x.getPaymentId())).map(x->x.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);long success=all.stream().filter(p->p.getStatus()==PaymentStatus.CAPTURED||p.getStatus()==PaymentStatus.PARTIALLY_REFUNDED||p.getStatus()==PaymentStatus.REFUNDED).count();long failed=all.stream().filter(p->p.getStatus()==PaymentStatus.FAILED).count();List<Map<String,Object>> trend=new ArrayList<>();for(int i=6;i>=0;i--){var d=LocalDate.now().minusDays(i);var dayTotal=all.stream().filter(p->p.getCreatedAt().atZone(ZoneOffset.UTC).toLocalDate().equals(d)).map(Payment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);trend.add(Map.of("date",d.toString(),"label",d.getDayOfWeek().getDisplayName(TextStyle.SHORT,Locale.ENGLISH),"amount",dayTotal));}return Map.of("totalVolume",volume,"successfulPayments",success,"failedPayments",failed,"refundAmount",refunded,"successRate",all.isEmpty()?0:Math.round(success*1000.0/all.size())/10.0,"pendingSettlement",volume.subtract(refunded).multiply(new BigDecimal("0.98")),"trend",trend,"methodBreakdown",methodBreakdown(all));}
 private Map<String,Long> methodBreakdown(List<Payment> all){var map=new LinkedHashMap<String,Long>();all.forEach(p->map.merge(p.getMethod(),1L,Long::sum));return map;}
}
